구분 추상 클래스 인터페이스 목적 IS-A 관계 CAN-DO 관계 상속 단일 상속만 다중 구현 가능 메서드 일부 구현 가능 기본적으로 추상 (Java 8+ default 허용) 생성자 가능 불가 접근 제어자 모두 가능 public만 변수 모든 타입 static final (상수) <pre><code>// 추상 클래스 - IS-A 관계
abstract class Vehicle {
    abstract void drive();
    void refuel() { System.out.println("주유"); }  // 구현 포함 가능
}

// 인터페이스 - CAN-DO 관계
interface Flyable { void fly(); }
interface Swimmable { void swim(); }

// 다중 구현
class FlyingFish extends Animal implements Flyable, Swimmable {
    public void fly() { }
    public void swim() { }
}
</code></pre>
